INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(1, 1, 'Singkamas', 'Jicama', 'Root Crop', , 'Karaniwang itinatanim ang singkamas sa Oktubre–Nobyembre at inaani sa panahon ng tag-init, dahil kailangan nito ng tuyo at maaraw na klima habang humihinog ang ugat nito. Ang tuyong kondisyon ay nakakatulong upang maiwasan ang pagbulok ng ugat na madalas mangyari kung sobra-sobra ang tubig sa lupa.', 120, 150);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(2, 1, 'Kamoteng Kahoy', 'Cassava', 'Root Crop', , 'Matibay ang kamoteng kahoy sa tagtuyot kaya karaniwang itinatanim ito sa panahon ng tag-init. Nakakatulong ang tuyong kondisyon upang mabawasan ang panganib ng mga sakit na dulot ng labis na halumigmig, at nagbibigay-daan ito para mas maayos at malusog ang paglaki ng ugat.', 240, 365);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(3, 1, 'Palay', 'Rice', 'Cereal / Grain', , 'Sa mga bayan ng Orani at Hermosa, itinatanim ang tinatawag na \"palagad\" o palay sa tag-init sa mga lugar na may sapat na patubig (irigasyon). Dahil may kontroladong suplay ng tubig mula sa irigasyon, kaya pa ring magtanim ng palay kahit walang ulan sa panahong ito.', 100, 120);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(4, 2, 'Gabi', 'Taro', 'Root Crop', , 'Lumalaki nang maayos ang gabi sa mainit at basang kapaligiran na may pantay na pamamahagi ng ulan. Kaya  mas inirerekomenda itong itanim sa tag-ulan upang tuluy-tuloy ang suplay ng tubig na kailangan nito sa paglaki — mas mababaw na pagtanim (4–5 cm) ang ginagamit sa panahong ito kumpara sa mas malalim na pagtanim (8–10 cm) kapag tag-init.', 210, 365);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(5, 2, 'Ube', 'Purple Yam', 'Root Crop', , 'Matagal humihinog ang ube kaya karaniwang itinatanim ito sa simula ng tag-ulan, upang may sapat at tuluy-tuloy na halumigmig sa lupa habang nasa unang yugto pa lamang ng paglaki ang halaman.', 240, 300);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(6, 3, 'Kamote', 'Sweet Potato', 'Root Crop', , 'Dalawang beses itinatanim ang kamote sa isang taon, una sa Mayo–Hunyo (simula ng tag-ulan) at ikalawa sa Oktubre–Disyembre (paglipat patungo sa tag-init), dahil kaya nitong umangkop sa parehong basa at tuyong kondisyon ng lupa, kaya  maituturing itong pananim para sa magkabilang panahon.', 90, 150);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(7, 1, 'Mais', 'Corn', 'Cereal / Grain', , 'Kumpara sa palay na kailangang nakababad sa tubig, ang mais ay nangangailangan lamang ng sapat na umingal o kontroladong patubig sa mga kritikal na yugto ng paglaki nito,', 70, 110);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(8, 1, 'Mani', 'Peanut', 'Legume', , 'Ang mani ay isang uri ng legumbre na may malalim na ugat. Hindi nito kailangan ng madalas na patubig kaya kayang-kaya nitong mabuhay gamit lamang ang natitirang basa o residual moisture sa lupa pagkatapos ng tag-ulan.', 90, 140);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(9, 2, 'Tubo', 'Sugarcane', 'Cash Crop', , 'Karaniwang itinatanim ito sa dulo ng tag-ulan hanggang unang bahagi ng tag-init (Oktubre–Disyembre) upang may sapat na tubig ito habang nag-uugat, at pagkatapos ay umaasa na lamang sa taglay nitong lalim ng ugat kapag dumating ang mas tuyong buwan hanggang sa pag-ani', 300, 360);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(10, 3, 'Talong', 'Eggplant', 'Gulay na Nagbubunga (Fruit Vegetable)', , 'Matibay sa init ng araw at kaya ring mabuhay kahit tag-ulan; laging may mataas na demand sa lokal na merkado.', 60, 90);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(11, 3, 'Ampalaya', 'Bitter Gourd', 'Gulay na Nagbubunga (Fruit Vegetable)', , 'Mataas ang sustansya at mabilis ibenta; mas madaling alagaan sa tag-araw upang maiwasan ang pagkaagnas ng ugat dulot ng baha.', 60, 70);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(12, 1, 'Kamatis', 'Tomato', 'Gulay na Nagbubunga (Fruit Vegetable)', , 'Masagana ang bunga kapag mainit ang panahon at walang malakas na ulan na sisira sa mga bulaklak nito', 60, 85);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(13, 3, 'Sitaw', 'String beans', 'Legumbre / Kuday (Legume / Pod Vegetable)', , 'Tumutulong na magbigay ng sustansya (nitrogen) sa lupa; mainam itanim kahit anong panahon para sa tuloy-tuloy na kita.', 50, 60);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(14, 1, 'Mangga', 'Mango', 'Prutas (Fruit Crop / Tree Crop)', , ' Nangangailangan ng mahabang tag-araw at mainit na panahon upang mamulaklak at matamis ang maging bunga.', 1825, 2920);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(15, 3, 'Pechay', 'Bok choy', 'Leafy vegetable', , 'MNapakabilis palakihin at anihin; madaling ibenta sa palengke dahil laging kasama sa mga lutuing Pilipino', 25, 30);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(16, 1, 'Pakwan', 'Watermelon', 'Prutas (Fruit Crop / Melon)', , 'Patok na patok na pampalamig tuwing tag-init; mabilis lumaki sa mabuhanging lupa pagkatapos ng tag-ulan.', 75, 90);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(17, 1, 'Mustasa', 'Mustard greens', 'Gulay na Nagbubunga (Fruit Vegetable)', , 'Matibay sa peste at hindi mapili sa uri ng lupa; mainam itanim sa mas malamig na mga buwan (October hanggang Pebrero).', 30, 40);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(18, 2, 'Kangkong', 'Water spinach', 'Leafy vegetable', , 'Kayang mabuhay kahit sa baha o basang-basang lupa; hindi nangangailangan ng maraming abono o masusing alaga.', 20, 40);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(19, 1, 'Munggo', 'Mung bean', 'Legume / Grain Legume', , 'Matibay sa init ng araw at kaya ring mabuhay kahit tag-ulan; laging may mataas na demand sa lokal na merkado.Perpektong pananim pagkatapos ng gapasan ng palay dahil pinayayaman nito ang nitrogen sa lupa para sa susunod na taniman.', 55, 60);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(20, 2, 'Sigarilyas', 'Winged bean', 'Legume', , 'Matibay sa init ng araw at kaya ring mabuhay kahit tag-ulan; laging may mataas na demand sa lokal na merkado.', 60, 90);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(21, 3, 'Kadyos', 'Pigeon Pea', 'Legume', , 'Matibay sa matinding tagtuyot at hindi namamatay kahit mapabayaan; mainam na bakod o pananggalang sa hangin.', 150, 180);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(22, 1, 'Kalabasa', 'Squash', 'Cucurbit / Fruit Vegetable', , 'Matagal masira pagkatapos anihin kaya madaling itabi o dalhin sa malalayong palengke nang hindi nabubulok.', 80, 100);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(23, 3, 'Upo', 'Bottle Gourd', 'Cucurbit / Fruit Vegetable', , 'Masagana ang bunga kapag mainit ang panahon basta\'t may balag; patok na sangkap sa mga ginisang ulam.', 60, 80);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(24, 2, 'Patola', 'Sponge Gourd', 'Cucurbit / Fruit Vegetable', , 'Gusto ang basang klima at mabilis mamunga tuwing buwan ng tag-ulan habang gumagapang sa mga trellis.', 50, 60);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(25, 3, 'Siling Labuyo / Siling Haba', 'Chili Pepper', 'Solanaceous / Spice', , 'Mataas ang halaga sa merkado at pwedeng anihin nang paulit-ulit sa loob ng mahigit isang taon.', 60, 75);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(26, 1, 'Sibuyas', 'Onion', 'Bulb Crop', , 'Nangangailangan ng malamig na gabi sa simula at mainit na sikat ng araw sa huli upang lumaki nang husto ang mga bombilya nito.', 90, 120);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(27, 3, 'Karrot', 'Carrot', 'Root Crop', , 'Gumagamit ng mga partikular na \"lowland variety\" na kayang tiisin ang init ng kapatagan, ngunit mas matamis ang ani kapag sumasabay sa mas malamig na mga buwan.', 75, 103);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(28, 1, 'Labanos', 'Radish', 'Root Crop', , 'Mas tama itanim sa mababang lugar kapag papalapit ang amihan dahil ang sobrang init ng tag-araw ay nagpapatigas at nagpapabutas sa loob ng ugat.', 45, 60);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(29, 1, 'Patani', 'Lima Bean', 'Legume / Climbing Vine', , 'Nangangailangan ng mahabang growing season sa patag na lupa na sumasabay sa tag-araw upang hindi pamahayan ng amag (fungal disease) ang makakapal nitong baging.', 150, 180);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(30, 3, 'Habicuelas', 'Snap Bean', 'Legume', , 'Ang barayti na Habicuelas ng snap bean ay kayang itanim sa kapatagan na hiyang sa init, bagamat mas masagana ang daloy ng bunga kapag hindi masyadong maulan.', 43, 52);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(31, 1, 'Cantaloupe', 'Cantaloupe', 'Cucurbit / Fruit Vegetable', , 'Kailangan ng patag at lantad sa araw na lupain; ang tuyong panahon ay selyo para maging matamis ang laman at hindi malaglag ang mga bulaklak nito.', 100, 105);
INSERT INTO `crops` (`CropID`, `SeasonID`, `CropName`, `EnglishName`, `CropType`, `Image`, `Reason`, `MinDaysToHarvest`, `MaxDaysToHarvest`) VALUES
(32, 3, 'Pipino', 'Cucumber', 'Cucurbit / Fruit Vegetable', , 'Ang ulan ng habagat (Mayo-Hulyo) ay nagbibigay ng natural na dilig, habang ang simula ng amihan (Oktubre-Disyembre) naman ay nagpapaganda sa hugis ng bunga.', 50, 65);

