CREATE TABLE `pest_diseases` (
  `PestDiseaseID` int(11) NOT NULL,
  `SeasonID` int(11) NOT NULL,
  `Name` varchar(150) NOT NULL,
  `Type` enum('Pest','Disease') NOT NULL,
  `Info` text DEFAULT NULL,
  `ManagementTips` text DEFAULT NULL,
  `Symptoms` text DEFAULT NULL,
  `Image` mediumblob DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `pest_diseases`
--

INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(1, 1, 'Rice Black Bug', 'Pest', 'Dumadapo sa mga palayan sa panahon ng paglipat mula tag-init patungong tag-ulan, na nagdudulot ng malaking pagkalugi sa ani. Mas mataas ang populasyon ng peste na ito sa panahon ng tag-init (Enero–Hunyo).', 'Maagang pagmonitor sa bukid gamit ang light trap, lalo na sa mga gabing may kabilugan ng buwan; gamitin ang mga rehistradong insecticide kung kinakailangan; panatilihing malinis ang paligid ng bukid sa mga damo.', '\"Bugburn\" — nangingitim at natutuyo ang mga dahon na parang tinamaan ng tagtuyot o apoy; naiipit na paglaki; walang laman o naninilaw na butil ng palay.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(2, 1, 'Rats (Daga)', 'Pest', 'Ang matagal na tagtuyot (hal. panahon ng El Niño) ay naiugnay sa malaking pagkalugi ng ani dulot ng daga at rice black bug.', 'Crop rotation at malinis na pagsasaka upang maalis ang tirahan ng daga; komunidad-based na pagbabantay at rat-trapping bago at sa panahon ng pananim.', 'Kinagat na puno at butil ng palay; mga natumbang tangkay malapit sa ugat; may butas sa pilapil; sirang butil sa imbakan.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(3, 1, 'Stem Borer', 'Pest', 'Ang stem borer moth ay isa ring pangunahing alalahanin sa panahon ng tag-init na dapat mahigpit na bantayan.', 'Paggamit ng pheromone trap o light trap para sa stem borer moth; alisin at sunugin ang mga natirang dayami pagkatapos anihin.', '\"Deadheart\" — namamatay at natutuyo ang sentrong usbong sa yugto ng paglaki; \"whitehead\" — walang laman at maputing uhay sa panahon ng pamumulaklak.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(4, 1, 'Cassava Mealybug', 'Pest', 'Isang lumalaganap na peste ng kamoteng kahoy na madalas dumami sa tuyo at pinagstress-na kondisyon ng lupa sa tag-init.', 'Gumamit ng malusog at malinis na pananim na cuttings; iwasang ilipat ang mga infested na sanga sa ibang bukid; alisin at sunugin ang matinding apektadong halaman; suportahan ang natural na kaaway tulad ng parasitic wasp.', 'Naipit at hindi normal na paglaki ng usbong (\"bunchy top\"); kulot at naninilaw na dahon; may malagkit na honeydew at itim na amag (sooty mold).', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(5, 2, 'Brown Planthopper', 'Pest', 'Umuunlad sa mainit at mahalumigmig na panahon, sumisipsip ng katas ng halaman at nagdudulot ng \"hopperburn\".', 'Iwasan ang labis na paggamit ng nitrogen fertilizer; huwag mag-spray ng insecticide nang madalas dahil napapatay din nito ang natural na kaaway; gumamit ng resistant na variety ng palay; alternate wetting and drying sa pamamahala ng tubig.', '\"Hopperburn\" — naninilaw pagkatapos ay namumula/natutuyo ang halaman sa bilog na bahagi ng bukid; nalalanta at naiipit ang paglaki.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(6, 2, 'Armyworms', 'Pest', 'Mabilis dumami ang armyworm sa tag-ulan at kilala sa pagmamartsa nang sama-sama sa buong bukid, lalo na pagkatapos ng malakas na ulan, at kumakain nang husto sa magdamag.', 'Linisin ang mga damo, araruhin ang lupa, gumamit ng light trap, at iwasang patayin ang mga gagamba dahil kumakain din sila ng armyworm.', 'Gutay-gutay at kinain na dahon; biglaang pagkawala ng dahon (defoliation) sa loob lang ng isang gabi; nakikitang grupo ng uod sa gilid ng bukid.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(7, 2, 'Golden Apple Snail (Golden Kuhol)', 'Pest', 'Umuunlad ang golden kuhol sa baha-bahang palayan sa tag-ulan at isa sa pangunahing peste na mula sa kabibe (mollusk) sa buong bansa, kabilang ang Bataan.', 'Manual na pagtitipon ng kuhol at mga itlog nito; paggamit ng itik bilang biological control; panatilihing mababaw (2–3 cm) ang tubig sa unang linggo ng pagtatanim; maglagay ng screen sa inlet/outlet ng tubig.', 'Naputol na mga punla malapit sa tubig; lumulutang na piraso ng punla; kulay-pink na kumpol ng itlog sa tangkay o pilapil.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(8, 2, 'Taro Leaf Blight', 'Disease', 'Sakit na dulot ng fungus na karaniwan sa gabi kapag tag-ulan dahil mabilis kumalat ang spora nito sa mahalumigmig at maulan na kondisyon.', 'Tamang agwat sa pagitan ng mga tanim para sa maayos na daloy ng hangin; alisin at sunugin ang mga apektadong dahon; iwasan ang overhead irrigation sa gabi.', 'Mabasang batik na lumalaki at nagiging kayumanggi/dilaw na sugat na may bilog na guhit (\"target spot\"); nalalanta ang dahon; may masamang amoy kung matindi na.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(9, 3, 'Sweet Potato Weevil (Bukbok ng Kamote)', 'Pest', 'Isa sa pinakamapaminsalang peste ng kamote sa Pilipinas; lumalala kapag tuyo at may bitak ang lupa dahil doon dumadaan ang uod papunta sa ugat.', 'Crop rotation; pagbunton ng lupa (hilling up) para matakpan ang mga bitak; gumamit ng malinis na pananim; maagang pag-ani upang maiwasan ang matagalang exposure ng ugat.', 'Mapait ang lasa at may butas-butas na ugat; nalalantang baging; maliliit na butas sa tangkay at ugat.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(10, 1, 'Aphids', 'Pest', 'Mabilis dumami sa mainit at tuyong panahon habang pinalalabas ang katas ng mga dahon ng singkamas.', 'Mag-spray ng insecticidal soap o neem oil; panatilihing sapat ang basâ ng lupa upang hindi masyadong ma-stress ang halaman sa tagtuyot.', 'Mangungunot at maninilaw ang mga dahon; naipit na paglaki ng ugat o singkamas.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(11, 1, 'Spider Mites', 'Pest', 'Lumalaganap sa tuyong klima at gumagawa ng manipis na sapot sa ilalim ng dahon ng singkamas.', 'Sprayan ng tubig o neem oil ang ilalim ng dahon upang magulo ang tirahan nito; panatilihing may sapat na moisture ang lupa.', 'Manipis na sapot sa ilalim ng dahon; pangingitim at pagkatuyo ng dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(12, 1, 'Fall Armyworm (FAW)', 'Pest', 'Pangunahing peste ng mais tuwing tag-araw na kumakain sa usbong at mga dahon nito.', 'Maglagay ng pheromone trap; gumamit ng biological control tulad ng Bacillus thuringiensis (Bt) o neem oil habang bata pa ang mga uod.', 'May mga butas ang gitnang usbong (whorl) na may kasamang dumi ng uod.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(13, 1, 'Corn Earworm', 'Pest', 'Peste na pumapasok at kumakain sa dulo ng bunga o puso ng mais.', 'Maglagay ng mineral oil o Bt sa buhok ng mais (silk) kapag katlalabas pa lamang nito.', 'Maglagay ng mineral oil o Bt sa buhok ng mais (silk) kapag katlalabas pa lamang nito.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(14, 1, 'Leafhoppers', 'Pest', 'Insekto na mabilis lumipat sa mga dahon ng mani upang sumipsip ng katas nito.', 'Mag-spray ng botanical pesticides; panatilihing malinis ang paligid sa mga damo.', 'Maninilaw ang gilid ng dahon na parang napaso (\"hopperburn\").', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(15, 1, 'Tomato Fruitworm', 'Pest', 'Pangunahing uod na bumubutas sa mismong bunga ng kamatis.', 'Mamulot ng mga uod gamit ang kamay o mag-spray ng rehistradong bio-pesticide (Bt) sa simula ng pamumulaklak.', 'May mga butas sa nangingitim o nabulok na bunga ng kamatis.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(16, 1, 'Whiteflies', 'Pest', 'Maliliit na puting insekto na sumisipsip ng katas at nagdadala ng sakit na virus sa kamatis.', 'Gumamit ng dilaw na sticky traps para sa whiteflies; mag-spray ng neem oil o soap solution.', 'Naninilaw at nagiging kulot ang mga dahon; may naiiwang malagkit na amag.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(17, 1, 'Mango Hoppers', 'Pest', 'Sumasalakay sa panahon ng pamumulaklak ng mangga tuwing tag-araw upang sumipsip ng katas.', 'Magbawas ng mga sanga (pruning) upang pumasok ang sikat ng araw; gumamit ng light trap sa gabi.', 'Pagtatagpas o pagkalaglag ng mga bulaklak; may malagkit na honeydew sa dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(18, 1, 'Cecid Fly', 'Pest', 'Insekto na nanganganak sa loob ng batang bunga ng mangga.', 'Mag-spray ng neem-based sprays sa panahon ng pagbubunga; ibaon ang mga nahulog na sirang prutas.', 'May maitim na batik sa balat at mga maliliit na uod sa loob ng prutas.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(19, 1, 'Thrips', 'Pest', 'Peste sa mga cucurbit at prutas na sumisira sa ibabaw ng dahon at balat ng prutas sa gitna ng mainit na panahon.', 'Maglagay ng silver reflective mulch; mag-spray ng neem oil o sabon na may tubig.', 'Nanggagaliting o nangungunot na dahon na may parang pilak na kulay; kalawangin o sirang balat ng prutas.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(20, 1, 'Flea Beetles', 'Pest', 'Maliliit na salagubang na tumatalon at kumakain sa dahon ng mga gulay tuwing amihan o tag-tuyot.', 'Takpan ng insect net ang mga plot; magbudbod ng abo ng kahoy o neem powder sa mga dahon sa madaling-araw.', 'Maliliit na butas-butas sa dahon na parang binaril (\"shot-hole\").', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(21, 1, 'Pod Borer', 'Pest', 'Uod na bumubutas at kumakain sa loob ng mga pod o balat ng mga legumbre.', 'Mag-spray ng neem-based insecticide bago lumabas ang mga pod; ayusin ang balag.', 'May butas ang mga pod at kinain ang mga buto sa loob.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(22, 1, 'Squash Beetle', 'Pest', 'Salagubang na kumakain sa mga dahon ng kalabasa tuwing tag-araw.', 'Kamayin ang paghuli sa mga salagubang at itlog nito sa ilalim ng dahon.', 'Nauubos ang laman ng dahon at veins na lang ang natitira.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(23, 1, 'Fruit Fly (Melon / Asian Fruit Fly)', 'Pest', 'Insekto na nag-iitlog sa loob ng batang bunga ng mga cucurbit at prutas kaya ito nabubulok.', 'Balutan ng papel o plastic wrapper ang mga batang prutas; gumamit ng protein bait trap; ibaon ang mga nabulok na prutas.', 'May nabulok at nangingitim na bahagi sa bunga na may uod sa loob; malambot na prutas.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(24, 1, 'Root-Knot Nematodes', 'Pest', 'Nematodes Microscopic na uod sa lupa na pumapasok at sumisira sa mga ugat ng gulay.', 'Mag-crop rotation; ibilad ang lupa sa araw (soil solarization); maglagay ng maraming compost o bio-nematicides sa lupa.', 'Pumuputok, nagkakabukol, o nagiging hindi pantay ang hugis ng ugat; may maraming hair roots.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(25, 2, 'Yam Beetle', 'Pest', 'Salagubang na dumadaan sa basang lupa upang kainin at butasin ang lumalaking ube.', 'Gumamit ng malinis na pananim; mag-crop rotation; araruhin nang maayos ang lupa bago magtanim.', 'May mga butas o tubong binutas sa ugat/ube.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(26, 2, 'Anthracnose (Fungal Disease)', 'Disease', 'Sakit na dulot ng fungus na mabilis kumalat sa mga dahon at bunga tuwing tag-ulan.', 'Gumamit ng malinis na pananim; panatilihing maayos ang drainage; mag-spray ng copper-based fungicide kapag matindi ang ulan.', 'Maitim na batik sa dahon na nagiging sanhi ng pagkalagas nito; pabilog at nakalubog na maitim na sugat sa bunga.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(27, 2, 'Sugarcane White Borer', 'Pest', 'Peste sa tubo na dumadami sa basang paligid at pumapasok sa loob ng tangkay.', 'Magpakawala ng kapaki-pakinabang na insekto tulad ng Trichogramma; putulin ang apektadong usbong.', 'Namamatay ang gitnang usbong (\"deadheart\").', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(28, 2, 'Woolly Aphid', 'Pest', 'Insekto na nag-iipon sa ilalim ng dahon ng tubo kapag tag-ulan.', 'Alisin ang mga apektadong dahon agad; suportahan ang mga natural na predator.', 'May mapuputi at parang bulak na pormasyon sa ilalim ng dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(29, 2, 'White Rust (Fungus)', 'Disease', 'Sakit na dulot ng labis na halumigmig at basang-basang lupa sa taniman.', 'Iwasan ang sobrang siksik na pagtatanim; siguraduhing may maayos na daanan ng tubig.', 'Mapuputing parang bukol o papule sa ilalim ng dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(30, 2, 'Snails (Suso/Kuhol)', 'Pest', 'Kumakain sa mga dahon ng gulay lalo na sa mga bahaing lugar.', 'Mamulot ng mga kuhol o suso gamit ang kamay; maglagay ng harang sa paligid ng plot.', 'Gutay-gutay na dahon dahil sa kain ng kuhol.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(31, 2, 'Powdery Mildew', 'Disease', 'Amag na dumadami sa ibabaw ng dahon kapag napakabasâ at mahalumigmig ang panahon.', 'Mag-spray ng baking soda solution o sulfur laban sa amag; panatilihing may sapat na agwat ang tanim.', 'May parang pulbos na puti sa ibabaw ng mga dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(32, 2, 'Downy Mildew', 'Disease', 'Sakit na dulot ng fungus sa basang dahon ng cucurbits kapag tag-ulan o mahalumigmig.', 'Siguraduhing matatag ang balag; iwasang magdilig sa dahon sa hapon; mag-spray ng copper-based fungicide.', 'Maninilaw at magiging kulay kape na korteng-kanto (angular) na batik sa dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(33, 3, 'Leafminers', 'Pest', 'Uod na gumagawa ng mga minahan o daanan sa loob ng dahon ng gulay.', 'Putulin at sunugin ang mga dahon na may minahan; gumamit ng yellow sticky traps.', 'May puting pasikot-sikot na guhit sa ibabaw ng dahon.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(34, 3, 'Cutworms', 'Pest', 'Uod na pumuputol ng mga batang tanim at punla sa pantay-lupa tuwing gabi.', 'Maglagay ng abo o neem cake sa base ng tangkay; mamulot sa gabi gamit ang ilaw; linisin ang debris.', 'Naputol na batang tangkay o punla malapit sa lupa.', );
INSERT INTO `pest_diseases` (`PestDiseaseID`, `SeasonID`, `Name`, `Type`, `Info`, `ManagementTips`, `Symptoms`, `Image`) VALUES
(35, 3, 'Cucumber Beetle', 'Pest', 'Salagubang na kumakain sa mga dahon at bulaklak ng mga cucurbit sa buong taon.', 'Araruhin ang lupa pagkatapos mag-ani para mamatay ang pupa; gumamit ng sticky trap; kamayin ang paghuli.', 'Kinakain ang dahon hanggang veins na lang ang matira (skeletonization)', );

